BEGIN; CREATE TABLE IF NOT EXISTS execution.position_management_decision_audit(audit_id bigserial PRIMARY KEY,lpforge_position_id text NOT NULL REFERENCES execution.owned_positions(lpforge_position_id),position_address text NOT NULL,observed_at timestamptz NOT NULL,active_bin_id integer,lower_bin_id integer NOT NULL,upper_bin_id integer NOT NULL,position_continuation_ev_lamports bigint,expected_close_cost_lamports bigint,uncertainty numeric,forecast_horizon_minutes integer,source_decision_id text,source_economics_id text,geometry_identity text NOT NULL,management_action text NOT NULL,exit_reason_family text NOT NULL,reason_codes jsonb NOT NULL DEFAULT '[]'::jsonb,confirmation_sequence_count integer NOT NULL DEFAULT 0 CHECK(confirmation_sequence_count>=0),valid_continuation_evidence boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(lpforge_position_id,observed_at)); CREATE INDEX IF NOT EXISTS position_management_decision_audit_live_idx ON execution.position_management_decision_audit(lpforge_position_id,observed_at DESC); CREATE TABLE IF NOT EXISTS execution.position_management_summaries(position_address text PRIMARY KEY,lifecycle_id text NOT NULL REFERENCES execution.position_lifecycles(lifecycle_id),entry_timestamp timestamptz NOT NULL,exit_timestamp timestamptz NOT NULL,hold_duration_seconds bigint NOT NULL,monitor_cycle_count integer NOT NULL,positive_continuation_ev_count integer NOT NULL,negative_continuation_ev_count integer NOT NULL,minimum_continuation_ev_lamports bigint,maximum_continuation_ev_lamports bigint,longest_confirmed_negative_sequence integer NOT NULL,terminal_continuation_ev_lamports bigint,terminal_expected_close_cost_lamports bigint,terminal_action text NOT NULL,terminal_reason text,entry_candidate_id text,entry_geometry_identity text,claim_count integer NOT NULL,realized_fees_lamports bigint NOT NULL,final_realized_pnl_lamports bigint,settlement_state text NOT NULL,compacted_at timestamptz NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb); CREATE INDEX IF NOT EXISTS position_management_summaries_settlement_idx ON execution.position_management_summaries(settlement_state,compacted_at DESC); COMMIT;
